function UIActionPointMapBossDialog:OnShow()
    xTry(function()
        -- 刷新资源条
        CfUtils.RefreshTopGoods(self.comp:GetResources())
        CfUtils.SetTopRightProjection(0)    -- 防止资源条是歪的
        CfUtils.SetUICameraProjection(true, 26)    -- 设置UI相机的透视模式和fov
        
        -- 刷新剩余奖励次数
        if isNotNull(self.Txt_CreateRoomRemainNums) then
            self.Txt_CreateRoomRemainNums.text = tostring(self.comp.remainCreateRewardTimes)
        end
        
        -- 切换boss
        local bossTypeId
        if isNotNull(self.controller.Argument.parameters)
        and isNotNull(self.controller.Argument.parameters.bossTypeId) then
            bossTypeId = self.controller.Argument.parameters.bossTypeId
        else
            bossTypeId = AnnihilationUtils.GetLastBossTypeId(self.activityPrefabId, self.activityContentId)
        end
        self:SwitchBoss(self.activityPrefabId, self.activityContentId, bossTypeId)

        -- 超稀有奖励
        self:FillSuperRareReward()
        
        -- 歼灭战战斗失败以后跳转养成会打开主界面场景，点击后退返回到这个界面的时候要把主界面场景关掉
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
    end)
end

function UIActionPointMapBossDialog:OnFocus(focus)
    if focus then
        -- 刷新资源条，防止跳转到购买界面再回来以后，资源栏被修改了
        CfUtils.RefreshTopGoods(self.comp:GetResources())

        -- 伤害奖励红点
        local redPoint = self.RT_RewardPreivewRedPoint
        if isNotNull(redPoint) then
            local redPointNum = self.comp:GetDamageRewardRedPoint()
            KTool.SetActive(redPoint, redPointNum > 0)
        end

        -- 排行榜每日奖励红点
        local redPoint = self.RT_RankRedPoint
        if isNotNull(redPoint) then
            local hasTips = self.comp:GetRankDailyRedPoint()
            KTool.SetActive(redPoint, hasTips >= 0)
        end

        -- 分榜每日奖励红点
        local redPoint = self.RT_BranchRankRedPoint
        if isNotNull(redPoint) then
            local hasTips = self.comp:GetBranchRankDailyRedPoint()
            KTool.SetActive(redPoint, hasTips >= 0)
        end

        -- 刷新消耗道具提示
        self:RefreshConsumePop(self.questId)
    end
end

