function UIActionPointMapBossDialog:InitComponent()
    self:InitBossNode()
    self.LT_DifficultyGroup = GetLuaBehaviour(self.RT_DifficultyGroup.gameObject, self.comp:GetHomeQuestBtnGroupLuaPath()).Env
    self.LT_DifficultyGroup:SetClickCallback(Bind(self, self.OnQuestBtnClicked))
    self.LT_DropRewardGroup = GetLuaBehaviour(self.RT_DropGroup.gameObject, self.comp:GetHomeDropItemGroupLuaPath()).Env
    if isNotNull(self.RT_SelectBossBtnL) then
        self.LT_SelectBossBtnL = GetLuaBehaviour(self.RT_SelectBossBtnL.gameObject, SelectBossBtnLuaPath).Env
        self.LT_SelectBossBtnL:SetClickCallback(Bind(self, self.OnSelectBossBtnClicked))
    end
    if isNotNull(self.RT_SelectBossBtnR) then
        self.LT_SelectBossBtnR = GetLuaBehaviour(self.RT_SelectBossBtnR.gameObject, SelectBossBtnLuaPath).Env
        self.LT_SelectBossBtnR:SetClickCallback(Bind(self, self.OnSelectBossBtnClicked))
    end
    UIEventProxy.Create(self.RT_CreateRoomBtn.gameObject).onPointerClick = Bind(self, self.OnCreateRoomBtnClick)

    -- 加入房间
    if isNotNull(self.RT_JoinRoomBtn) then
        KTool.SetActive(self.RT_JoinRoomBtn, false)
    end
    -- 加入房间剩余次数
    if isNotNull(self.Txt_JoinRoomRemainNums) then
        KTool.SetActive(self.Txt_JoinRoomRemainNums.transform.parent, false)
    end
    -- 奖励预览
    if isNotNull(self.RT_RewardPreviewBtn)
    and isNotNull(self.comp.OnRewardPreviewBtnClicked) then
        UIEventProxy.Create(self.RT_RewardPreviewBtn.gameObject).onPointerClick = Bind(self.comp, self.comp.OnRewardPreviewBtnClicked)
        -- 伤害奖励红点
        local redPoint = self.RT_RewardPreivewRedPoint
        if isNotNull(redPoint) then
            local redPointNum = self.comp:GetDamageRewardRedPoint()
            KTool.SetActive(redPoint, redPointNum > 0)
        end
    end
    -- 排行榜
    if isNotNull(self.RT_RankBtn)
    and isNotNull(self.comp.OnRankBtnClicked) then
        UIEventProxy.Create(self.RT_RankBtn.gameObject).onPointerClick = Bind(self.comp, self.comp.OnRankBtnClicked)
        -- 排行榜每日奖励红点
        local redPoint = self.RT_RankRedPoint
        if isNotNull(redPoint) then
            local hasTips = self.comp:GetRankDailyRedPoint()
            KTool.SetActive(redPoint, hasTips >= 0)
        end
    end
    -- 排行榜分榜
    if isNotNull(self.RT_BranchRankBtn)
    and isNotNull(self.comp.OnBranchRankBtnClicked) then
        SetButtonAction(self.RT_BranchRankBtn, Bind(self.comp, self.comp.OnBranchRankBtnClicked))
        -- 分榜每日奖励红点
        local redPoint = self.RT_BranchRankRedPoint
        if isNotNull(redPoint) then
            local hasTips = self.comp:GetBranchRankDailyRedPoint()
            KTool.SetActive(redPoint, hasTips >= 0)
        end
    end
    -- 分榜倒计时
    if isNotNull(self.Txt_BranchRankTime)
    and isNotNull(self.comp.GetBranchRankRemainTime) then
        local remainTime = self.comp:GetBranchRankRemainTime()
        if remainTime <= 0 then
            CfUtils.FillText(self.Txt_BranchRankTime, localize("已结束"))
        else
            CfUtils.FillText(self.Txt_BranchRankTime, CfUtils.GetTimeHMS10(remainTime))
        end
        self.comp.callbackOnBranchRankCountDown = function(remainTime)
            if remainTime <= 0 then
                CfUtils.FillText(self.Txt_BranchRankTime, localize("已结束"))
            else
                CfUtils.FillText(self.Txt_BranchRankTime, CfUtils.GetTimeHMS10(remainTime))
            end
        end
    end
end

--- 初始化boss立绘节点的map，键是歼灭战类型表id
function UIActionPointMapBossDialog:InitBossNode()
    self.bossNodeMap = {
        [1] = self.RT_Boss1,
        [2] = self.RT_Boss2,
        [3] = self.RT_Boss3,
    }
end

function UIActionPointMapBossDialog:SwitchBoss(activityPrefabId, activityContentId, bossTypeId)
    self.bossTypeId = bossTypeId
    self:RefreshBoss(activityPrefabId, activityContentId, bossTypeId)
    self:RefreshDifficultyBtnGroup(activityPrefabId, activityContentId, bossTypeId)
    self:RefreshSelectBossBtn(activityPrefabId, activityContentId, bossTypeId)
end

--- 显示boss背景图和boss的立绘
---@param typeId number 歼灭战类型表id
function UIActionPointMapBossDialog:RefreshBoss(activityType, activityId, typeId)
    local vo = self.comp:GetTypeVo(typeId)
    if not vo then
        return
    end
    self.ARImg_Bg:LoadSprite(vo.bgPath)

    if isNotNull(self.curBossNode) then
        KTool.SetActive(self.curBossNode, false)
    end
    
    self.curBossNode = self.bossNodeMap[typeId]
    KTool.SetActive(self.curBossNode, true)
end

--- 刷新难度按钮组
---@param typeId number 歼灭战类型表id
function UIActionPointMapBossDialog:RefreshDifficultyBtnGroup(activityPrefabId, activityContentId, bossTypeId)
    local questId = AnnihilationUtils.GetLastQuestId(activityPrefabId, activityContentId, bossTypeId)
    self.LT_DifficultyGroup:Refresh(activityPrefabId, activityContentId, bossTypeId, questId)
end

function UIActionPointMapBossDialog:OnQuestBtnClicked(activityType, activityId, questId)
    self.questId = questId
    -- 刷新掉落奖励
    self.LT_DropRewardGroup:RefreshGroup(questId)
    -- 刷新消耗道具提示
    self:RefreshConsumePop(questId)
end

-- 刷新消耗道具提示
function UIActionPointMapBossDialog:RefreshConsumePop(questId)
    if isNull(questId) then
        return
    end
    -- 刷新消耗道具提示
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    CfUtils.FillCommonBtnConsumePopNode(self.RT_ConsumePop, vo.costItem, (vo.costNum + vo.costNumLose))
    -- 奖励次数清零以后，不显示消耗道具提示
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
    if checkNumber(comp.remainCreateRewardTimes) <= 0 then
        KTool.SetActive(self.RT_ConsumePop, false)
    end
end

--- 点击创建房间按钮
function UIActionPointMapBossDialog:OnCreateRoomBtnClick()
    local isUnlocked, tipsDesc = AnnihilationUtils.IsUnlockBossQuest(self.activityPrefabId, self.activityContentId, self.bossTypeId, self.questId)
    if not isUnlocked then
        GameUtils.Toast(tipsDesc)
        return
    end

    if not KNManager.isConnected then
        GameUtils.Toast(localize('TCP连接失败，请检查网络后重试'))
        return
    end
    RegionQuestMgr:GetInstance():OverseaRegionalBossCreateRoomReq(self.activityType, self.activityContentId, self.activityUuid, self.activityPrefabId,
    self.bossTypeId, self.questId, function(data)

        local t = {}
        local dialogs = UIModule.CurrentScreen.dialogs
        for _, dialog in pairs(dialogs) do
            table.insert(t, dialog.Argument)
        end
        UIModule.OpenDialog({ id = self.comp:GetTeamUITypeId() }, t)
    end)
end

--- 刷新选择boss按钮
---@param typeId any
function UIActionPointMapBossDialog:RefreshSelectBossBtn(activityType, activityId, typeId)
    local leftId = (typeId + 3 - 1) % 3
    leftId = leftId == 0 and 3 or leftId
    local rightId = (typeId + 3 + 1) % 3
    rightId = rightId == 0 and 3 or rightId
    -- print("[歼灭战] 切boss", leftId, rightId)
    if isNotNull(self.LT_SelectBossBtnL) then
        self.LT_SelectBossBtnL:SwitchBoss(activityType, activityId, leftId)
    end
    if isNotNull(self.LT_SelectBossBtnR) then
        self.LT_SelectBossBtnR:SwitchBoss(activityType, activityId, rightId)
    end
end

function UIActionPointMapBossDialog:OnSelectBossBtnClicked(activityPrefabId, activityContentId, bossTypeId)
    self:SwitchBoss(activityPrefabId, activityContentId, bossTypeId)
end

function UIActionPointMapBossDialog:FillSuperRareReward()
    if isNull(self.SuperRareReward) then
        return
    end

    local lb = GetLuaBehaviour(self.SuperRareReward.gameObject, "Game.Activity.LinkageBoss.SuperRareReward")
    if isNull(lb) then
        return
    end
    lb.Env:Refresh(self.comp)
end

return UIActionPointMapBossDialog
